// ─── Utility ─────────────────────────────────────────────────────────────────
function clamp(v, lo = 0.05, hi = 0.95) { return Math.max(lo, Math.min(hi, v)); }

// ─── Build country objects ────────────────────────────────────────────────────
function buildCountries() {
  return RAW_COUNTRIES.map(c => {
    const { iso3, es, eo, pol = 0.5, scores } = c;

    // ES category scores — derived from tech×SC real data, bucketed by category
    // Map our real category data: use tech-averaged scores per ES category
    // Since real category breakdown is in the pipeline, we approximate here
    // using overall score ± tech-SC variation
    const esCategories = {};
    for (const cat of ES_CATEGORIES) {
      // Pull category-specific signal from available tech scores
      const techVals = Object.values(scores).map(s => s.es).filter(v => v != null);
      const mean = techVals.length ? techVals.reduce((a,b)=>a+b,0)/techVals.length : es;
      const spread = techVals.length ? Math.max(...techVals) - Math.min(...techVals) : 0.15;
      // Use deterministic per-category offset based on hash
      let h = 0; for (let i=0;i<(iso3+cat.key).length;i++) h = (h*31 + (iso3+cat.key).charCodeAt(i)) >>> 0;
      const offset = ((h % 1000) / 1000 - 0.5) * spread * 0.6;
      esCategories[cat.key] = clamp(mean + offset, 0.05, 0.95);
    }

    // EO category scores
    const eoCategories = {};
    for (const cat of EO_CATEGORIES) {
      const techVals = Object.values(scores).map(s => s.eo).filter(v => v != null);
      const mean = techVals.length ? techVals.reduce((a,b)=>a+b,0)/techVals.length : eo;
      const spread = techVals.length ? Math.max(...techVals) - Math.min(...techVals) : 0.15;
      let h = 0; for (let i=0;i<(iso3+cat.key).length;i++) h = (h*31 + (iso3+cat.key).charCodeAt(i)) >>> 0;
      const offset = ((h % 1000) / 1000 - 0.5) * spread * 0.6;
      eoCategories[cat.key] = clamp(mean + offset, 0.05, 0.95);
    }

    // Tech × SC breakdown — use real scores where available, fill missing
    const techBreakdown = {};
    for (const tech of TECHNOLOGIES) {
      techBreakdown[tech.key] = {};
      for (const sc of SUPPLY_CHAINS) {
        const key = `${tech.key}|${sc.key}`;
        const s = scores[key] || {};
        // Fill missing with overall average ± small deterministic jitter
        let h = 0; const jk = iso3+tech.key+sc.key;
        for (let i=0;i<jk.length;i++) h = (h*31 + jk.charCodeAt(i)) >>> 0;
        const jitter = ((h % 1000) / 1000 - 0.5) * 0.08;
        techBreakdown[tech.key][sc.key] = {
          es: clamp(s.es != null ? s.es : es + jitter),
          eo: clamp(s.eo != null ? s.eo : eo + jitter),
          pol: s.pol != null ? s.pol : pol,
        };
      }
    }

    // Flat techScores array
    const techScores = [];
    for (const tech of TECHNOLOGIES) {
      for (const sc of SUPPLY_CHAINS) {
        const d = techBreakdown[tech.key]?.[sc.key];
        if (d) {
          techScores.push({
            tech: tech.key,
            sc:   sc.key,
            es:   d.es,
            eo:   d.eo,
            psi:  +(d.es * 0.4 + d.eo * 0.4 + (pol || 0.5) * 0.2).toFixed(3),
          });
        }
      }
    }

    return { ...c, esCategories, eoCategories, techBreakdown, techScores, policy: pol };
  });
}

const COUNTRIES = buildCountries();
const COUNTRY_MAP  = Object.fromEntries(COUNTRIES.map(c => [c.iso3, c]));
const ISONUM_MAP   = Object.fromEntries(COUNTRIES.map(c => [c.isoN, c]));

// ─── Region bounding boxes for map zoom ─────────────────────────────────────
const REGION_BOUNDS = {
  'North America':  [-170, 10, -50, 85],
  'South America':  [-85, -60, -30, 15],
  'Europe':         [-28, 34, 45, 72],
  'Africa':         [-20, -40, 55, 38],
  'Middle East':    [25, 10, 68, 43],
  'Asia-Pacific':   [60, -50, 180, 55],
  'Europe/Asia':    [20, 40, 140, 75],
  'Central Asia':   [45, 36, 90, 58],
};

// ─── Partnership scoring ──────────────────────────────────────────────────────
const ALIGN_COMPAT = {
  west:    { west:0.90, brics:0.50, neutral:0.62, opec:0.52, rival:0.15 },
  brics:   { west:0.50, brics:0.72, neutral:0.62, opec:0.55, rival:0.55 },
  neutral: { west:0.62, brics:0.62, neutral:0.65, opec:0.55, rival:0.40 },
  opec:    { west:0.52, brics:0.55, neutral:0.55, opec:0.76, rival:0.35 },
  rival:   { west:0.15, brics:0.55, neutral:0.40, opec:0.35, rival:0.72 },
};

function computePartnership(home, partner) {
  if (home.iso3 === partner.iso3) return null;
  const align = ALIGN_COMPAT[home.align]?.[partner.align] ?? 0.5;
  let h = 0; const jk = home.iso3+partner.iso3+'psi';
  for (let i=0;i<jk.length;i++) h=(h*31+jk.charCodeAt(i))>>>0;
  const noise = ((h%1000)/1000 - 0.5)*0.07;

  const esNeed  = 1 - (home.es || 0.5);
  const eoPart  = partner.eo || 0.5;
  const climateSynergy = Math.max(0, 1 - Math.abs((home.policy||0.5) - (partner.policy||0.5)));
  const friendshore = clamp((align*2 + esNeed*3 + eoPart*3 + (partner.psi||0.5)*2) / 10 * (0.9 + 0.1*climateSynergy) + noise);

  const pDemand  = clamp((partner.eoCategories.technology_demand + partner.eoCategories.consumption) / 2);
  const exportP  = clamp((pDemand*3 + (home.eo||0.5)*2 + align*2 + partner.eoCategories.energy_access*2) / 9 + noise);

  const need     = clamp((1 - (partner.eo||0.5) + 1 - (partner.es||0.5)) / 2);
  const potential= clamp((partner.esCategories.reserves + partner.esCategories.minerals_trade) / 2);
  const devP     = clamp((need*3 + potential*3 + (home.eo||0.5)*2 + align*2) / 10 + noise);

  return {
    friendshore:    +friendshore.toFixed(3),
    export_partner: +exportP.toFixed(3),
    development:    +devP.toFixed(3),
    composite:      +clamp(friendshore*0.4 + exportP*0.4 + devP*0.2 + noise*0.5).toFixed(3),
  };
}

function getPartners(homeIso3, type = 'friendshore') {
  const home = COUNTRY_MAP[homeIso3];
  if (!home) return [];
  return COUNTRIES
    .filter(p => p.iso3 !== homeIso3)
    .map(p => ({ ...p, scores: computePartnership(home, p) }))
    .filter(p => p.scores)
    .sort((a, b) => (b.scores[type] || 0) - (a.scores[type] || 0));
}

// ─── Tooltip helper: top N industries by index ───────────────────────────────
function topIndustries(country, indexKey = 'es', n = 3) {
  const combos = [];
  for (const tech of TECHNOLOGIES) {
    for (const sc of SUPPLY_CHAINS) {
      const d = country.techBreakdown[tech.key]?.[sc.key];
      if (!d) continue;
      let score;
      if (indexKey === 'policy') {
        score = d.eo * 0.6 + ((country.policy||country.pol) ?? 0.5) * 0.4;
      } else {
        score = d[indexKey];
      }
      if (score == null || isNaN(score)) continue;
      combos.push({ icon: tech.icon, tech: tech.label, sc: sc.label, score: +score.toFixed(3) });
    }
  }
  return combos.sort((a, b) => b.score - a.score).slice(0, n);
}

// ─── Utility ──────────────────────────────────────────────────────────────────
function scoreLabel(v) {
  if (v >= 0.75) return { text:'Strong',   cls:'score-strong' };
  if (v >= 0.55) return { text:'Moderate', cls:'score-moderate' };
  if (v >= 0.35) return { text:'Weak',     cls:'score-weak' };
  return              { text:'Very Weak', cls:'score-vweak' };
}
function fmtScore(v) { return (v * 100).toFixed(1); }

const REGIONS = [...new Set(COUNTRIES.map(c => c.region))].sort();

const METHODOLOGY = {
  es:`The Energy Security Index measures resilience across 9 weighted categories: Foreign Dependency×6, Production×6, Consumption×5, Energy Imports×4, Reserves×4, Trade Risk×4, Minerals Trade×4, Energy Access×4, Energy Prices×2. Higher score = greater domestic energy security.`,
  eo:`The Economic Opportunity Index measures competitive positioning across 10 categories: Technology Demand×4, Trade×3, Production×3, Energy Prices×3, Investment×3, Energy Access×3, Foreign Dependency×3, Cost Competitiveness×3, Consumption×3, Tech Readiness×2. Higher score = stronger opportunity.`,
  psi:`The Partnership Strength Index assesses bilateral partnership quality: Friendshore (40%) × Export fit (40%) × Development (20%). Directional — computed from home country perspective.`,
  weights_es:`ES weights (config/weights.yml): Foreign Dependency×6, Production×6, Consumption×5, Energy Imports×4, Reserves×4, Trade Risk×4, Minerals Trade×4, Energy Access×4, Energy Prices×2`,
  weights_eo:`EO weights: Technology Demand×4, Trade×3, Production×3, Energy Prices×3, Investment×3, Energy Access×3, Foreign Dependency×3, Cost Competitiveness×3, Consumption×3, Tech Readiness×2`,
};

window.OSI_DATA = {
  COUNTRIES, COUNTRY_MAP, ISONUM_MAP,
  ES_CATEGORIES, EO_CATEGORIES,
  TECHNOLOGIES, SUPPLY_CHAINS,
  REGIONS, REGION_BOUNDS, METHODOLOGY,
  getPartners, computePartnership, topIndustries, scoreLabel, fmtScore,
};
